// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        c.newGrantProposal(recipient, amount);
        uint256 pid = c.proposalCount();
        (address storedRecipient, uint256 storedAmount) = c.mapPID_grant(pid);
        assertTrue(
            storedRecipient == recipient && storedAmount == amount && pid >= 1,
            "grant must be stored under the incremented proposal ID"
        );
    }
}
